mapper.select:
INSERT INTO vehicle_run_observation(
raw_observation_id, line_id, direction_id, stop_pattern_id, provider_vehicle_id, provider_run_id, destination_stop_id,
current_stop_id, current_sequence, service_type, movement_status, latitude, longitude, speed_kph, bearing_degrees,
position_source, observed_at, received_at
) VALUES (
#{rawObservationId}, #{lineId}, #{directionId}, #{stopPatternId}, #{providerVehicleId}, #{providerRunId}, #{destinationStopId},
#{currentStopId}, #{currentSequence}, #{serviceType}, #{movementStatus}, #{latitude}, #{longitude}, #{speedKph}, #{bearingDegrees},
#{positionSource}, #{observedAt}, #{receivedAt}
) RETURNING id

mapper.delete:
DELETE FROM vehicle_run_observation
WHERE id IN (
SELECT id
FROM vehicle_run_observation
WHERE received_at  <  #{receivedBefore}
ORDER BY received_at ASC, id ASC
LIMIT #{limit}
)

mapper.select:
SELECT 
FROM vehicle_run_observation
WHERE line_id = #{lineId}
AND provider_vehicle_id = #{providerVehicleId}
AND observed_at  >=  #{observedAfter}
ORDER BY observed_at DESC, received_at DESC, id DESC
LIMIT #{limit}
